#!/usr/bin/env python3
"""Build editable Hyperframes scenes from the camera choreography in shots.json."""
import json
from pathlib import Path
P=Path(__file__).resolve().parent
cfg=json.loads((P/'shots.json').read_text())
(P/'assets/shots.js').write_text('window.GP_SHOTS='+json.dumps(cfg,separators=(',',':'))+';\n')
css='''
*{box-sizing:border-box}html,body{margin:0;width:1920px;height:1080px;overflow:hidden;font-family:Inter,sans-serif}body{background:#edf2f8;color:#14233e}.clip{position:absolute;inset:0}.scene{position:absolute;inset:0;overflow:hidden;background:#edf2f8}.scene.dark{background:#11161f;color:#fff}.world{position:absolute;inset:0;perspective:1800px;perspective-origin:50% 50%;overflow:hidden}.camera{position:absolute;inset:0;transform-style:preserve-3d;transform-origin:960px 540px}.device{position:absolute;left:210px;top:310px;width:1500px;height:703px;transform-style:preserve-3d}.base{position:absolute;inset:0;background:#f2f3f7;border:1px solid #c0c9d4;border-radius:14px;box-shadow:0 38px 80px #14233e2e,0 4px 0 #a9b2c0,0 10px 0 #8995a5;transform:translateZ(-12px)}.pane{position:absolute;overflow:hidden;border-radius:2px;background:white;box-shadow:0 10px 30px #14233e12;backface-visibility:hidden}.pane img{position:absolute;width:1520px;height:712.5px;max-width:none;display:block;pointer-events:none}.pane.side{left:0;top:0;width:254px;height:703px;border-radius:14px 0 0 14px}.pane.bar{left:254px;top:0;width:1246px;height:59px;border-radius:0 14px 0 0}.pane.list{left:254px;top:59px;width:428px;height:644px}.pane.read{left:682px;top:59px;width:818px;height:644px;border-radius:0 0 14px 0}.side img{left:0;top:0}.bar img{left:-254px;top:0}.list img{left:-254px;top:-59px}.read img{left:-682px;top:-59px}.headline{position:absolute;left:150px;top:64px;z-index:100;font-size:88px;line-height:1.04;letter-spacing:-4px;font-weight:900;margin:0;max-width:1600px;color:#14233e}.headline em{font-style:normal;color:#007aff}.subtitle{position:absolute;left:154px;top:264px;font-size:33px;font-weight:400;letter-spacing:-.7px;z-index:100;color:#344963}.single .subtitle{top:177px}.single .headline{top:67px}.dark .headline,.dark .subtitle{color:#fff}.dark .headline em{color:#58a8ff}.demo-note{position:absolute;left:154px;bottom:44px;font-size:28px;color:#344963;z-index:100;background:transparent;padding:0;left:auto;right:154px;bottom:auto;top:86px}.dark .demo-note{background:transparent;color:#c9d5e5}.thread-demo{position:absolute;inset:0;background:#fff;color:#24272d;padding:24px 30px;overflow:hidden}.thread-top{font-weight:700;font-size:29px;line-height:1.3;margin-bottom:15px}.control{display:flex;align-items:center;gap:9px;color:#344963;background:#eef1f5;padding:10px 15px;border-radius:7px;font-size:28px;font-weight:700;width:max-content}.control .tick{font-size:25px}.messages{position:relative;margin-top:17px;height:485px}.message{position:absolute;left:0;width:758px;border:1px solid #d8dee7;background:#fff;padding:22px 26px;border-radius:9px;box-shadow:0 10px 24px #14233e0a}.message .who{font-weight:700;font-size:28px;line-height:36px}.message .when{float:right;font-size:28px;font-weight:400;color:#515b6b}.message .body{font-size:30px;line-height:1.4;margin-top:14px}.message.old{top:0;height:178px}.message.latest{top:200px;height:252px;border-left:5px solid #007aff}.message.latest .when{color:#005bbd}.message.latest .body strong{font-weight:700}.zoom-demo .thread-top{margin-bottom:22px}.zoom-bar{font-size:28px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #d8dee7;padding-bottom:18px;color:#344963}.zoom-value{display:flex;align-items:center;gap:18px;font-weight:700}.percent{position:relative;width:90px;height:38px;display:inline-block;color:#005bbd}.percent span{position:absolute;inset:0}.zoom-message{padding-top:26px;font-size:30px;line-height:1.48;width:490px;transform-origin:0 0}.zoom-message p{margin:0 0 18px}.zoom-message .sender{font-size:28px;font-weight:700;margin-bottom:24px}.keycap{position:absolute;right:173px;bottom:50px;background:#fff;border:1px solid #bfcad8;border-bottom:5px solid #a9b6c7;border-radius:12px;padding:14px 26px;font-size:32px;font-weight:700;color:#14233e;z-index:100}.labels-demo{position:absolute;left:0;top:58px;right:0;bottom:0;background:#f4f4f7;font-size:30px;color:#313844;padding-top:14px}.label-heading{font-size:30px;padding:0 20px;display:flex;justify-content:space-between;margin-bottom:15px}.label-inbox,.label-row{height:55px;display:flex;align-items:center;gap:11px;padding:0 18px;font-weight:400}.label-inbox{background:#dce5f4;margin:0 9px;border-radius:5px;color:#005bbd}.tag{width:18px;height:15px;background:#526174;clip-path:polygon(0 0,65% 0,100% 50%,65% 100%,0 100%)}.label-inbox .tag{background:#007aff}.label-rows{position:relative;margin-top:8px}.label-row{position:absolute;left:9px;right:9px;border-radius:5px;background:#f4f4f7}.handle{font-size:28px;color:#526174;margin-left:auto}.label-projects{top:0}.label-clients{top:62px}.label-design{top:124px}.label-team{top:186px}.label-more{top:260px;font-size:28px;color:#526174}.theme-dark{position:absolute;inset:0;transform-style:preserve-3d}.theme-dark .pane{background:#23292b}.theme-dark .base{background:#23292b;border-color:#526174;box-shadow:0 38px 90px #0006,0 5px 0 #435167,0 10px 0 #253144}.theme-line{position:absolute;left:150px;top:70px;z-index:101;font-size:88px;line-height:1.04;font-weight:900;letter-spacing:-4px;color:#fff}.theme-line em{font-style:normal;color:#58a8ff}.hero-brand{position:absolute;left:150px;top:70px;display:flex;align-items:center;gap:24px;z-index:110}.hero-brand img{width:92px;height:92px}.hero-brand h1{position:static;margin:0;font-size:94px;line-height:1;letter-spacing:-4px}.hero .subtitle{left:154px;top:196px;font-size:38px}.hero .device{top:340px}.hero-cta{position:absolute;right:154px;top:82px;z-index:110;background:#007aff;border-radius:12px;color:white;font-weight:700;font-size:34px;padding:25px 35px}.hero-url{position:absolute;right:154px;top:181px;font-size:28px;color:#c9d5e5;z-index:110}.hero .demo-note{bottom:40px}.hero .pane{box-shadow:none}.arrow{display:inline-block;margin-left:16px}
'''
css+='''
.filing-list{position:absolute;inset:0;background:#fff;padding:17px 24px;color:#24272d}.filing-list-title{font-size:28px;color:#344963;border-bottom:1px solid #d8dee7;padding-bottom:15px}.file-row{position:absolute;left:14px;right:14px;padding:20px 20px;border-bottom:1px solid #d8dee7;background:white;font-size:28px;line-height:1.35}.file-row strong{font-size:31px;display:block;margin-bottom:7px}.file-primary{top:64px;height:220px}.file-next{top:284px;height:155px}.file-selected{top:439px;height:159px;background:#007aff;color:white}.file-badge{position:absolute;left:20px;bottom:18px;border:1px solid #99bce5;border-radius:5px;background:#edf4fc;padding:7px 13px;color:#005bbd;font-size:30px;font-weight:700}.file-unread{display:inline-block;width:10px;height:10px;background:#007aff;border-radius:50%;position:absolute;left:4px;top:31px}.filing-toast{position:absolute;left:270px;bottom:26px;z-index:30;color:white;background:#303944;border-radius:8px;padding:18px 25px;font-size:30px;box-shadow:0 7px 20px #0003}.filing-toast span{color:#9bcdff;font-weight:700;margin-left:30px}.film-pointer{position:absolute;left:0;top:0;width:44px;height:44px;z-index:80;transform-style:preserve-3d;pointer-events:none}
'''
css=css.replace('perspective:1800px',f'perspective:{cfg["perspective"]}px')
(P/'assets/film.css').write_text(css)
# Uniform camera driver, not six copies of ad-hoc animation. Properties are true 3D poses.
engine='''window.GPFilm={camera(tl,id){const shot=window.GP_SHOTS.shots.find(s=>s.id===id);const target="#"+id+"-camera";let state={x:0,y:0,z:0,rotationX:0,rotationY:0,rotationZ:0};for(const move of shot.camera){const from=move.from||state;const to={...from,...move.to};const intensity=window.GP_SHOTS.intensity;const pose=p=>Object.fromEntries(Object.entries(p).map(([k,v])=>[k,v*intensity]));tl.fromTo(target,{...pose(from),force3D:true},{...pose(to),duration:move.duration,ease:move.ease,force3D:true,immediateRender:move.at===0},move.at);state=to;}return shot;}, title(tl,id,at,style){const t="#"+id+"-title";if(style==="wipe")tl.fromTo(t,{clipPath:"inset(0 100% 0 0)"},{clipPath:"inset(0 0% 0 0)",duration:.47,ease:"power4.out"},at);else if(style==="ink")tl.fromTo(t,{color:"#a6b1c1",opacity:0},{color:"#14233e",opacity:1,duration:.23,ease:"power2.out"},at);else tl.fromTo(t,{opacity:0,y:20},{opacity:1,y:0,duration:.38,ease:"power4.out"},at);}};
'''
(P/'assets/camera.js').write_text(engine)
def panels(id,dark=False):
    src='assets/gmail-pro-dark.jpg' if dark else 'assets/gmail-pro-light.jpg'
    return '<div class="base"></div>'+''.join(f'<div id="{id}-{k}" class="pane {k}"><img id="{id}-{k}-img" src="{src}" alt="Gmail Pro {k} pane"></div>' for k in ['side','bar','list','read'])
def message_scene(id,zoom=False):
    if zoom:
        return f'''<div class="thread-demo zoom-demo"><div class="thread-top">The launch checklist is ready</div><div class="zoom-bar"><span>↶ Reply &nbsp; · &nbsp; Forward</span><div class="zoom-value">− <div class="percent"><span id="{id}-100">100%</span><span id="{id}-150">150%</span></div> +</div></div><div id="{id}-body" class="zoom-message"><div class="sender">Maya Chen</div><p>Hi Alex,</p><p>The final checklist is ready.</p><p>Let’s make something great.</p></div></div>'''
    return f'''<div class="thread-demo"><div class="thread-top">The launch checklist is ready</div><div id="{id}-control" class="control"><span class="tick">↑</span> Newest first</div><div class="messages"><div id="{id}-old" class="message old"><div class="who">Alex Rivera <span class="when">Earlier</span></div><div class="body">Ready for one last review?</div></div><div id="{id}-latest" class="message latest"><div class="who">Maya Chen <span class="when">Latest reply</span></div><div class="body"><strong>The final checklist is ready.</strong><br>Let’s make something great.</div></div></div></div>'''
def label_demo(id):
    return f'''<div class="labels-demo"><div class="label-heading">Mailboxes <span>↕ ＋</span></div><div class="label-inbox"><i class="tag"></i>Inbox</div><div class="label-rows"><div id="{id}-projects" class="label-row label-projects"><i class="tag"></i>Projects<span class="handle">⠿</span></div><div id="{id}-clients" class="label-row label-clients"><i class="tag"></i>Clients<span class="handle">⠿</span></div><div class="label-row label-design"><i class="tag"></i>Design<span class="handle">⠿</span></div><div class="label-row label-team"><i class="tag"></i>Team<span class="handle">⠿</span></div></div></div>'''
def filing_demo():
    return '<div class="filing-list"><div class="filing-list-title">Inbox</div><div id="filing-row" class="file-row file-primary"><i id="filing-unread" class="file-unread"></i><strong id="filing-sender">Alex Rivera</strong><div>Next release ideas</div><div id="filing-badge" class="file-badge">Projects</div></div><div id="filing-next" class="file-row file-next"><strong>Jordan Lee</strong>Coffee next week?</div><div id="filing-selected" class="file-row file-selected"><strong>Maya Chen</strong>The launch checklist<br>is ready</div></div>'
for shot in cfg['shots']:
    id=shot['id'];hero=id=='hero';dark=hero
    classes='scene'+(' dark hero single' if hero else ' single' if '<br>' not in shot['title'] else '')
    ui=panels(id,dark)
    # Mount illustrative interactions in the matching real pane.
    if id in ('newest','zoom'):
        needle=f'<div id="{id}-read" class="pane read"><img id="{id}-read-img" src="assets/gmail-pro-light.jpg" alt="Gmail Pro read pane"></div>'
        ui=ui.replace(needle,f'<div id="{id}-read" class="pane read">'+message_scene(id,id=='zoom')+'</div>')
    if id=='filing':
        needle=f'<div id="{id}-list" class="pane list"><img id="{id}-list-img" src="assets/gmail-pro-light.jpg" alt="Gmail Pro list pane"></div>'
        ui=ui.replace(needle,f'<div id="{id}-list" class="pane list">'+filing_demo()+'</div>')
        ui+='<div id="filing-toast" class="filing-toast">Moved to Projects <span>Undo</span></div><svg id="filing-pointer" class="film-pointer" viewBox="0 0 40 40"><path d="M4 2 4 32 12 24 18 38 24 35 18 22 31 22Z" fill="white" stroke="#14233e" stroke-width="2.5"/></svg>'
    if id=='labels':
        needle=f'<div id="{id}-side" class="pane side"><img id="{id}-side-img" src="assets/gmail-pro-light.jpg" alt="Gmail Pro side pane"></div>'
        ui=ui.replace(needle,needle[:-6]+label_demo(id)+'</div>')
    title=(f'<div id="{id}-brand" class="hero-brand"><img id="{id}-logo" src="assets/icon128.png" alt="Gmail Pro icon"><h1 id="{id}-title" class="headline">{shot["title"]}</h1></div>' if hero else f'<h1 id="{id}-title" class="headline">{shot["title"]}</h1>')
    subtitle=f'<div id="{id}-subtitle" class="subtitle">{shot["subtitle"]}</div>' if shot.get('subtitle') else ''
    note=f'<div id="{id}-note" class="demo-note">Illustrative demo · Fictional mailbox</div>' if id in ('newest','zoom','labels','filing') else ''
    extra=f'<div id="{id}-key" class="keycap">⌘ +</div>' if id=='zoom' else ''

    if hero:extra+=f'<div id="{id}-cta" class="hero-cta">Add to Chrome <span class="arrow">↗</span></div><div id="{id}-url" class="hero-url">gmail-pro.netlify.app</div>'
    script=f'''const tl=gsap.timeline({{paused:true}});const shot=GPFilm.camera(tl,"{id}");GPFilm.title(tl,"{id}",shot.titleAt,shot.titleStyle);'''
    if subtitle:script+=f'tl.fromTo("#{id}-subtitle",{{opacity:0}},{{opacity:1,duration:.25}},shot.titleAt+.16);'
    if id in ('reveal','workspace'):
        for k,fac in [('side',.4),('list',.7),('read',1)]:
            script+=f'tl.fromTo("#{id}-{k}",{{z:0}},{{z:{shot["depth"]*fac},duration:.75,ease:"power2.inOut"}},.5);'
    if id=='newest':
        script+='''tl.fromTo("#newest-control",{backgroundColor:"#eef1f5",color:"#344963"},{backgroundColor:"#007aff",color:"#fff",duration:.12},1.82);
        tl.fromTo("#newest-latest",{y:0,z:0},{y:-200,z:46,duration:.92,ease:"power3.inOut"},1.82); // beat-grid: latest reply lands6.01s
        tl.fromTo("#newest-old",{y:0},{y:274,duration:.92,ease:"power3.inOut"},1.82);'''
    if id=='zoom':
        script+='''tl.fromTo("#zoom-150",{opacity:0},{opacity:1,duration:.12},1.58);tl.fromTo("#zoom-100",{opacity:1},{opacity:0,duration:.12},1.58);
        tl.fromTo("#zoom-body",{scale:1},{scale:1.5,duration:.6,ease:"power3.inOut"},1.58); // beat-grid: body zoom lands10.37s
        tl.fromTo("#zoom-key",{y:12,opacity:0},{y:0,opacity:1,duration:.28,ease:"power4.out"},1.10);'''
    if id=='labels':
        script+='''tl.fromTo("#labels-clients",{y:0,z:0,backgroundColor:"#f4f4f7",color:"#313844"},{y:-62,z:60,backgroundColor:"#007aff",color:"#fff",duration:.65,ease:"power3.inOut"},.90);
        tl.fromTo("#labels-projects",{y:0},{y:62,duration:.65,ease:"power3.inOut"},.90);
        tl.fromTo("#labels-clients",{z:60,backgroundColor:"#007aff",color:"#fff"},{z:0,backgroundColor:"#f4f4f7",color:"#313844",duration:.3,immediateRender:false},1.60);
        '''
    if id=='filing':
        script+='''tl.fromTo("#filing-pointer",{x:800,y:560,opacity:0},{x:365,y:266,opacity:1,duration:.36,ease:"power3.inOut"},.99);
        tl.fromTo("#filing-badge",{backgroundColor:"#edf4fc",color:"#005bbd"},{backgroundColor:"#007aff",color:"#fff",duration:.12},1.35);
        tl.fromTo("#filing-unread",{opacity:1},{opacity:0,duration:.1},1.48);
        tl.fromTo("#filing-row",{x:0,opacity:1,z:0},{x:330,opacity:0,z:42,duration:.38,ease:"power3.in"},1.62);
        tl.fromTo(["#filing-next","#filing-selected"],{y:0},{y:-220,duration:.38,ease:"power3.inOut"},1.62);
        tl.fromTo("#filing-toast",{opacity:0,y:15},{opacity:1,y:0,duration:.28,ease:"power4.out"},1.92); // beat-grid: archive acknowledgement18.02s
        tl.fromTo("#filing-pointer",{opacity:1},{opacity:0,duration:.15,immediateRender:false},1.65);
        tl.fromTo("#filing-stage",{backgroundColor:"#edf2f8"},{backgroundColor:"#11161f",duration:.3},3.87);
        tl.fromTo("#filing-title",{opacity:1},{opacity:0,duration:.15},3.87);
        tl.fromTo("#filing-note",{color:"#344963"},{color:"#c9d5e5",duration:.3},3.87);'''
    if hero:
        script+='''tl.fromTo("#hero-logo",{rotationY:-40,opacity:0},{rotationY:0,opacity:1,duration:.65,ease:"power4.out"},.18); // beat-locked: hero starts 19.66s
        tl.fromTo("#hero-cta",{clipPath:"inset(0 100% 0 0)"},{clipPath:"inset(0 0% 0 0)",duration:.5,ease:"power4.out"},.65);
        tl.fromTo("#hero-url",{opacity:0},{opacity:1,duration:.3},.95);'''
    script=script.replace('z:46',f'z:{shot["depth"]}').replace('z:60',f'z:{shot["depth"]}')
    script+=f'window.__timelines["{id}"]=tl;'
    html=f'''<template><style>#root{{position:absolute;inset:0;}}</style><div id="root" data-composition-id="{id}" data-width="1920" data-height="1080"><div id="{id}-content" class="clip" data-start="0" data-duration="{shot['duration']}"><div id="{id}-stage" class="{classes}"><div class="world" data-layout-allow-overflow><div id="{id}-camera" class="camera"><div class="device">{ui}</div></div></div>{title}{subtitle}{note}{extra}</div></div></div><script>{script}</script></template>'''
    (P/'compositions'/f'{id}.html').write_text(html)
hosts='\n'.join(f'<div id="{s["id"]}" class="clip" data-composition-id="{s["id"]}" data-composition-src="compositions/{s["id"]}.html" data-start="{s["start"]}" data-duration="{s["duration"]}" data-track-index="{i+1}" data-width="1920" data-height="1080"></div>' for i,s in enumerate(cfg['shots']))
audio='<audio id="film-music" class="clip" src="assets/music.mp3" data-start="0" data-duration="24" data-volume="0.30" data-fade-in="0.25" data-fade-out="1.5" data-track-index="10"></audio>'
for i,(t,src,vol,dur) in enumerate([(1.42,'impact',.45,.18),(5.09,'click',.55,.04),(6.01,'impact',.40,.18),(9.77,'click',.55,.04),(13.45,'click',.4,.04),(16.64,'click',.55,.04),(17.29,'impact',.35,.18),(19.66,'impact',.45,.18)]):
    audio+=f'<audio id="sfx-{i}" class="clip" src="assets/{src}.ogg" data-start="{t}" data-duration="{dur}" data-volume="{vol}" data-track-index="{11+i}"></audio>'
(P/'index.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=1920,height=1080"><title>Gmail Pro — A cleaner way to use Gmail</title><link rel="stylesheet" href="assets/film.css"><script src="assets/gsap.min.js"></script><script src="assets/shots.js"></script><script src="assets/camera.js"></script></head><body><div id="root" data-composition-id="main" data-start="0" data-duration="24" data-width="1920" data-height="1080" data-fps="30" data-motion-blur="on" data-motion-blur-shutter="{cfg['shutter']}">{hosts}{audio}</div><script>window.__timelines=window.__timelines||{{}};const tl=gsap.timeline({{paused:true}});window.__timelines["main"]=tl;</script></body></html>''')
print('Built six configurable 3D scenes: 24s, 1920×1080, 30fps.')
